 3	public final class BinarySearch {
 4	    private static final int NOT_FOUND_INDEX = -1;
 5	    private static final int[] SAMPLE_VALUES = {2, 3, 4, 10, 40};
 6	    private static final int SAMPLE_TARGET = 10;
 7	
 8	    private BinarySearch() {
 9	    }
10	
11	    public static int binarySearch(int[] values, int target) {
12	        Objects.requireNonNull(values, "values");
13	
14	        int low = 0;
15	        int high = values.length - 1;
16	
17	        while (low <= high) {
18	            int mid = low + (high - low) / 2;
19	            int candidate = values[mid];
20	
21	            if (candidate == target) {
22	                return mid;
23	            }
24	
25	            if (candidate < target) {
26	                low = mid + 1;
27	            } else {
28	                high = mid - 1;
29	            }
30	        }
31	
32	        return NOT_FOUND_INDEX;
33	    }
34	
35	    private static String searchResultMessage(int result) {
36	        if (result == NOT_FOUND_INDEX) {
37	            return "Element is not present in array";
38	        }
39	
40	        return "Element is present at index " + result;
41	    }
42	
43	    public static void main(String[] args) {
44	        int result = binarySearch(SAMPLE_VALUES, SAMPLE_TARGET);
45	        System.out.println(searchResultMessage(result));
46	    }
